 35	export function registerRepositoryRoutes(
 36	    router: Router,
 37	    repoManager: RepositoryManager,
 38	    appConfig: AppConfig,
 39	    errorLogManager?: ErrorLogManager,
 40	): void {
 41	    /**
 42	     * Look up a repository by ID.
 43	     *
 44	     * Sends a `404` response and returns `undefined` when the repository
 45	     * cannot be found.
 46	     *
 47	     * @param res          - The outgoing HTTP response (used to send the 404 error).
 48	     * @param repositoryId - The ID of the repository to look up.
 49	     * @returns The matching `Repository` on success, or `undefined` when a 404
 50	     *          has already been written to `res`.
 51	     */
 52	    function resolveRepository(
 53	        res: ServerResponse,
 54	        repositoryId: string,
 55	    ): Repository | undefined {
 56	        const repo = repoManager.getById(repositoryId);
 57	        if (repo === undefined) {
 58	            sendError(res, 404, `Repository with ID "${repositoryId}" not found.`);
 59	            return undefined;
 60	        }
 61	        return repo;
 62	    }
