 66	    // ------------------------------------------------------------------
 67	    router.get('/api/repositories', (
 68	        _req: IncomingMessage,
 69	        res: ServerResponse,
 70	        _params: Record<string, string>,
 71	    ): void => {
 72	        const repos = repoManager.list();
